   153  /* Frees element ELEM.  Unlinks it from the cache tree and LRU list. */
   154  static void
   155  cache_elem_free (GDBM_FILE dbf, cache_elem *elem)
   156  {
   157    _gdbm_cache_tree_delete (dbf->cache_tree, elem->ca_node);
   158    lru_unlink_elem (dbf, elem);
   159    elem->ca_next = dbf->cache_avail;
   160    dbf->cache_avail = elem;
   161    dbf->cache_num--;
   162  }
