   164  /* Free the least recently used cache entry. */
   165  static inline int
   166  cache_lru_free (GDBM_FILE dbf)
   167  {
   168    cache_elem *last = dbf->cache_lru;
   169    if (last->ca_changed)
   170      {
   171        if (_gdbm_write_bucket (dbf, last))
   172          return -1;
   173      }
   174    cache_elem_free (dbf, last);
   175    return 0;
   176  }
