    82  /* Grow the disk file of DBF to SIZE bytes in length. Fill the
    83     newly allocated space with zeros. */
    84  int
    85  _gdbm_file_extend (GDBM_FILE dbf, off_t size)
    86  {
    87    size_t page_size = sysconf (_SC_PAGESIZE);
    88    char *buf;
    89    off_t file_end;
    90
    91    file_end = lseek (dbf->desc, 0, SEEK_END);
    92    if (!file_end)
    93      {
    94        GDBM_SET_ERRNO (dbf, GDBM_FILE_SEEK_ERROR, FALSE);
    95        return -1;
    96      }
    97    size -= file_end;
    98    if (size > 0)
    99      {
   100        if (size < page_size)
   101          page_size = size;
   102        buf = calloc (1, page_size);
   103        if (!buf)
   104          {
   105            GDBM_SET_ERRNO (dbf, GDBM_MALLOC_ERROR, FALSE);
   106            return -1;
   107          }
   108
   109        /* Invalidate file_size */
   110        dbf->file_size = -1;
   111
   112        while (size)
   113          {
   114            ssize_t n = write (dbf->desc, buf,
   115                               size < page_size ? size : page_size);
   116            if (n <= 0)
   117              {
   118                GDBM_SET_ERRNO (dbf, GDBM_FILE_WRITE_ERROR, TRUE);
   119                break;
   120              }
   121            size -= n;
   122          }
   123        free (buf);
   124        if (size)
   125          return -1;
   126      }
   127    return 0;
   128  }
